  UNION ALL
  MATCH (s)-[:HAS_INVENTORY]->(i0:Inventory)-[r1:CONTAINS_SET|CONTAINS_MINIFIG]->(x1)-[:HAS_INVENTORY]->(i1:Inventory)-[r2:CONTAINS_SET|CONTAINS_MINIFIG]->(x2)-[:HAS_INVENTORY]->(i2:Inventory)-[h2:HAS_PART]->(:Part {part_num: '3024'})
